//! Dart code generation, ported from the 1.1.1 plugin generators.

mod colors;
mod effects;
pub mod js;
pub mod naming;
mod text_styles;
mod variables;

use std::collections::HashMap;

use crate::error::Error;
use crate::snapshot::{Alias, Collection, Mode, ResolvedType, Snapshot, Variable, VariableValue};

const HEADER: &str = "// This file is generated by Flart plugin.\n\
// Please, do not edit this file.\n\
// ignore_for_file: unnecessary_import, type=lint\n\
\n\
import 'dart:ui';\n\
import 'package:flutter/material.dart';\n\
\n";

const MAX_ALIAS_DEPTH: usize = 64;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    Colors,
    TextStyles,
    Effects,
    Variables,
}

impl Kind {
    pub const ALL: [Kind; 4] = [
        Kind::Colors,
        Kind::TextStyles,
        Kind::Effects,
        Kind::Variables,
    ];

    pub fn file_stem(self) -> &'static str {
        match self {
            Kind::Colors => "colors",
            Kind::TextStyles => "text_styles",
            Kind::Effects => "effects",
            Kind::Variables => "variables",
        }
    }

    /// Whether the snapshot has anything of this kind to generate.
    pub fn is_present_in(self, snapshot: &Snapshot) -> bool {
        match self {
            Kind::Colors => !snapshot.paint_styles.is_empty(),
            Kind::TextStyles => !snapshot.text_styles.is_empty(),
            Kind::Effects => !snapshot.effect_styles.is_empty(),
            Kind::Variables => variables::local_collections(snapshot).next().is_some(),
        }
    }

    /// Modes a `--modes` name can select for this kind: the plugin's mode
    /// source, or every local collection's modes for variables.
    pub fn selectable_modes(self, snapshot: &Snapshot) -> Vec<Mode> {
        match self {
            Kind::Variables => variables::local_collections(snapshot)
                .flat_map(|c| c.modes.clone())
                .collect(),
            kind => modes(kind, snapshot).unwrap_or_default(),
        }
    }
}

impl std::str::FromStr for Kind {
    type Err = String;

    fn from_str(text: &str) -> Result<Self, Self::Err> {
        Kind::ALL
            .into_iter()
            .find(|kind| kind.file_stem() == text)
            .ok_or_else(|| {
                format!(
                    "unknown kind {text:?}; expected colors, text_styles, effects, or variables"
                )
            })
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Options {
    pub theme_extensions: bool,
    pub include_font_name: bool,
}

/// Generates one Dart file. `selected_mode_ids` mirrors the plugin's mode
/// dialog: `None` is the no-selection path, `Some` lists ids from [`modes`].
pub fn generate(
    kind: Kind,
    snapshot: &Snapshot,
    options: Options,
    selected_mode_ids: Option<&[String]>,
) -> Result<String, Error> {
    let index = Index::new(snapshot);
    ensure_unique_names(kind, &index, snapshot)?;
    let selected = selected_mode_ids.filter(|ids| !ids.is_empty());
    Ok(match kind {
        Kind::Colors => colors::generate(&index, snapshot, selected),
        Kind::TextStyles => text_styles::generate(&index, snapshot, options, selected),
        Kind::Effects => effects::generate(&index, snapshot, selected),
        Kind::Variables => variables::generate(&index, snapshot, options, selected),
    })
}

fn ensure_unique_names(kind: Kind, index: &Index, snapshot: &Snapshot) -> Result<(), Error> {
    let styles = |scope: &str, names: Vec<&str>, prefix: &str| {
        let entries = names.into_iter().enumerate().map(|(position, name)| {
            (
                naming::format_style_name(name, position, prefix),
                name.to_string(),
            )
        });
        ensure_unique(scope, entries)
    };
    match kind {
        Kind::Colors => {
            let names = snapshot
                .paint_styles
                .iter()
                .map(|s| s.name.as_str())
                .collect();
            styles("paint styles", names, "color")
        }
        Kind::TextStyles => {
            let names = snapshot
                .text_styles
                .iter()
                .map(|s| s.name.as_str())
                .collect();
            styles("text styles", names, "textStyle")
        }
        Kind::Effects => {
            let names = snapshot
                .effect_styles
                .iter()
                .map(|s| s.name.as_str())
                .collect();
            styles("effect styles", names, "effectStyle")
        }
        Kind::Variables => variables::local_collections(snapshot).try_for_each(|collection| {
            let entries = collection
                .variable_ids
                .iter()
                .filter_map(|id| index.variable(id))
                .map(|v| (variables::identifier(index, v), v.name.clone()));
            ensure_unique(&format!("collection {}", collection.name), entries)
        }),
    }
}

fn ensure_unique(
    scope: &str,
    entries: impl Iterator<Item = (String, String)>,
) -> Result<(), Error> {
    let mut seen: HashMap<String, String> = HashMap::new();
    for (name, source) in entries {
        if let Some(first) = seen.get(&name) {
            return Err(Error::DuplicateIdentifier {
                scope: scope.to_string(),
                name,
                first: first.clone(),
                second: source,
            });
        }
        seen.insert(name, source);
    }
    Ok(())
}

/// The modes the plugin offered for `kind`, or `None` when it offered none.
pub fn modes(kind: Kind, snapshot: &Snapshot) -> Option<Vec<Mode>> {
    let index = Index::new(snapshot);
    match kind {
        Kind::Colors => colors::modes(&index, snapshot),
        Kind::TextStyles => text_styles::modes(&index, snapshot),
        Kind::Effects => effects::modes(&index, snapshot),
        Kind::Variables => variables::modes(snapshot),
    }
}

/// Lookups over a snapshot, the way the Plugin API answers them.
pub(crate) struct Index<'a> {
    variables: HashMap<&'a str, &'a Variable>,
    collections: HashMap<&'a str, &'a Collection>,
}

impl<'a> Index<'a> {
    fn new(snapshot: &'a Snapshot) -> Self {
        Self {
            variables: snapshot
                .variables
                .iter()
                .map(|v| (v.id.as_str(), v))
                .collect(),
            collections: snapshot
                .collections
                .iter()
                .map(|c| (c.id.as_str(), c))
                .collect(),
        }
    }

    pub fn variable(&self, id: &str) -> Option<&'a Variable> {
        self.variables.get(id).copied()
    }

    pub fn collection(&self, id: &str) -> Option<&'a Collection> {
        self.collections.get(id).copied()
    }

    /// The collection's modes when it has more than one; the plugin used the
    /// first such collection a style was bound to as the mode source.
    pub fn multi_mode_collection_of(&self, alias: &Alias) -> Option<Vec<Mode>> {
        let variable = self.variable(&alias.id)?;
        let collection = self.collection(&variable.variable_collection_id)?;
        (collection.modes.len() > 1).then(|| collection.modes.clone())
    }

    /// A variable's value in `mode_id`, following aliases.
    pub fn value_in_mode(
        &self,
        variable: &'a Variable,
        mode_id: &str,
    ) -> Option<(&'a VariableValue, ResolvedType)> {
        match variable.values_by_mode.get(mode_id)? {
            VariableValue::Alias(alias) => self.resolve_alias(alias),
            value => Some((value, variable.resolved_type)),
        }
    }

    /// Follows an alias chain, reading each target in its collection's
    /// default mode, as Figma does for a node with no explicit mode set.
    pub fn resolve_alias(&self, alias: &Alias) -> Option<(&'a VariableValue, ResolvedType)> {
        let mut target = self.variable(&alias.id)?;
        for _ in 0..MAX_ALIAS_DEPTH {
            let collection = self.collection(&target.variable_collection_id)?;
            match target.values_by_mode.get(&collection.default_mode_id)? {
                VariableValue::Alias(next) => target = self.variable(&next.id)?,
                value => return Some((value, target.resolved_type)),
            }
        }
        None
    }
}

fn mode_name(modes: Option<&[Mode]>, mode_id: &str) -> String {
    modes
        .into_iter()
        .flatten()
        .find(|mode| mode.mode_id == mode_id)
        .map_or_else(|| mode_id.to_string(), |mode| mode.name.clone())
}
